        int wo = conv_out_size(wi, pad_w, dilation_w, x, stride_w);
        int group = arg->get_int("group_count");
		int forw = arg->get_int("forw");

        int need_wrw = (forw == 0 ? 1 : (forw & 4 ? 1 : 0));
        if(need_wrw == 0)
            return false;

        if(tunable->fma_type == IGEMM_GTC_TUNABLE_FMA_TYPE_WMMA){
