{
    int num_cu;
    int gcn_arch = 0;
    int num_simd = 4 * 16;
    hipDeviceProp_t dev_prop;
    hipDevice_t dev;
    HIP_CALL(hipGetDevice(&dev));
    HIP_CALL(hipGetDeviceProperties(&dev_prop, dev));
    num_cu = dev_prop.multiProcessorCount;
    gcn_arch = get_gcn_arch(dev_prop.gcnArchName);
